package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.plugin.variable.Val;

public class RefuseClosedClaim {
    // A claim belongs to the period its due-by falls in: one due by a date inside a closed period cannot be edited,
    // opened, settled or voided.
    public void refuse(@Val Claim claim, Periods periods) throws ClaimInClosedPeriodException {
        Period closed = periods.closedOn(claim.sheetId(), claim.dueBy());
        if (closed != null) {
            throw new ClaimInClosedPeriodException("The period " + closed.name() + " is closed: its claims cannot change.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyProof {
    // A SETTLED or VOID claim takes no more proofs. Stored only if the claim still has its loaded status and count, so
    // a claim settled or voided meanwhile by another user is refused.
    public void apply(@Val Claim claim, Claims claims, Out<ClaimResponse> responseOut) throws ClaimProofRefusedException {
        if (claim.status() == ClaimStatus.SETTLED || claim.status() == ClaimStatus.VOID) {
            throw new ClaimProofRefusedException("A " + claim.status() + " claim takes no more proofs.");
        }
        Claim proved = claims.addProof(claim);
        if (proved == null) {
            throw new ClaimProofRefusedException("The claim changed meanwhile: try again.");
        }
        responseOut.set(ClaimResponse.from(proved));
    }
}

